import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Library: none — native interpolate for smooth fill

const { fontFamily: interFamily } = loadInter();



export type ComponentNameProps = Record<string, any>;

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#071732",
  transparentBackground = false,
  durationInSeconds = 8,
  topText = "FULL",
  bottomText = "HUNGRY",
  textColor = "#ffffff",
  fillColor = "#ffffff",
  outlineColor = "#ffffff",
  textStrokeColor = "#000000",
  textStrokeWidth = 4,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  
  // Canvas scale factor for responsive sizing
  const s = Math.min(width, height) / 1080; 

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Fade-in entrance: fully hidden before frame 5, fully visible at frame 20
  const entranceStart = 5;
  const entranceEnd = 20;
  const opacity = interpolate(
    frame,
    [entranceStart, entranceEnd],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Fill animation: begins after entrance and spans exactly 5 seconds
  const fillStart = entranceEnd;
  const fillEnd = fillStart + 5 * fps;
  
  const fillProgress = interpolate(
    frame,
    [fillStart, fillEnd],
    [0, 1],
    { 
      extrapolateLeft: "clamp", 
      extrapolateRight: "clamp", 
      easing: Easing.inOut(Easing.cubic) 
    }
  );

  // Responsive dimensions based on height/width canvas boundaries
  const barWidth = 300 * s;
  const barHeight = 1150 * s;
  const borderWidth = 12 * s;
  const borderRadius = 80 * s;
  const gap = 45 * s;
  const fontSize = 90 * s;
  const strokeWidthPx = textStrokeWidth * s;

  // CSS Text stroke style using webkit-text-stroke
  const textStrokeStyle: React.CSSProperties = {
    WebkitTextStroke: `${strokeWidthPx}px ${textStrokeColor}`,
    paintOrder: "stroke fill",
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, alignItems: 'center', justifyContent: 'center' }}>
      <div 
        style={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          opacity,
          transition: "none"
        }}
      >
        <div style={{ 
          fontSize, 
          color: textColor, 
          fontWeight: 900, 
          marginBottom: gap,
          letterSpacing: 3 * s,
          textTransform: 'uppercase',
          transition: "none",
          ...textStrokeStyle
        }}>
          {topText}
        </div>
        
        {/* Outer Bar Container */}
        <div style={{
          width: barWidth,
          height: barHeight,
          border: `${borderWidth}px solid ${outlineColor}`,
          borderRadius,
          position: 'relative',
          overflow: 'hidden',
          transition: "none"
        }}>
          {/* Inner Fill Element growing from bottom */}
          <div style={{
            position: 'absolute',
            bottom: 0,
            left: 0,
            right: 0,
            height: `${fillProgress * 100}%`,
            backgroundColor: fillColor,
            transition: "none"
          }} />
        </div>
        
        <div style={{ 
          fontSize, 
          color: textColor, 
          fontWeight: 900, 
          marginTop: gap,
          letterSpacing: 3 * s,
          textTransform: 'uppercase',
          transition: "none",
          ...textStrokeStyle
        }}>
          {bottomText}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ComponentName;